#include <windows.h>
#include <msi.h>
#include <msiquery.h>
#include <cstdio>
int wmain(int argc,wchar_t**argv){if(argc!=2)return 2;MSIHANDLE db=0;UINT error=MsiOpenDatabaseW(argv[1],MSIDBOPEN_TRANSACT,&db);if(error)return error;const wchar_t* queries[]={L"UPDATE `ControlEvent` SET `Ordering`=999 WHERE `Dialog_`='ExitDialog' AND `Control_`='Finish' AND `Event`='EndDialog'",L"DELETE FROM `ControlCondition` WHERE `Dialog_`='ExitDialog' AND `Control_`='OptionalCheckBox'",L"INSERT INTO `ControlCondition` (`Dialog_`,`Control_`,`Action`,`Condition`) VALUES ('ExitDialog','OptionalCheckBox','Show','WIXUI_EXITDIALOGOPTIONALCHECKBOXTEXT AND NOT REMOVE')",L"DELETE FROM `ControlCondition` WHERE `Dialog_`='ExitDialog' AND `Control_`='OptionalText'",L"INSERT INTO `ControlCondition` (`Dialog_`,`Control_`,`Action`,`Condition`) VALUES ('ExitDialog','OptionalText','Show','WIXUI_EXITDIALOGOPTIONALTEXT AND NOT REMOVE')"};for(auto sql:queries){MSIHANDLE view=0;error=MsiDatabaseOpenViewW(db,sql,&view);if(!error)error=MsiViewExecute(view,0);if(view)MsiCloseHandle(view);if(error){MsiCloseHandle(db);return error;}}error=MsiDatabaseCommit(db);MsiCloseHandle(db);if(!error)puts("Finish checkbox enabled for installation and repair");return error;}
